response:
{
  "scenarios": [
    {
      "id": 1,
      "title": "The Morning Fog",
      "difficulty": 2,
      "narrative": "You wake up after only 2 hours of sleep. Your alarm is blaring, and you have a full day ahead. Your body feels heavy, and a wave of dread washes over you as you think about the tasks waiting. The anxiety is already whispering that you can't handle this.",
      "options": [
        {
          "id": "A",
          "text": "Hit snooze and scroll on your phone to distract yourself from the dread.",
          "strategy": "Avoidant"
        },
        {
          "id": "B",
          "text": "Sit up, take three deep breaths, and name three things you can see in the room to ground yourself.",
          "strategy": "Emotionally Regulated"
        },
        {
          "id": "C",
          "text": "Immediately start listing every task you need to do today to plan your way out of the anxiety.",
          "strategy": "Analytical"
        },
        {
          "id": "D",
          "text": "Tell yourself you're a failure for not getting enough sleep and that the day is already ruined.",
          "strategy": "Self-Critical"
        }
      ]
    },
    {
      "id": 2,
      "title": "The Overwhelmed Inbox",
      "difficulty": 3,
      "narrative": "You open your work inbox to find 47 unread emails. Three are marked 'URGENT' in red. Your heart rate spikes. You feel the familiar tightness in your chest, and your mind starts racing with catastrophic thoughts about what you might have missed.",
      "options": [
        {
          "id": "A",
          "text": "Close the laptop and walk away, deciding to deal with it later when you 'feel ready.'",
          "strategy": "Avoidant"
        },
        {
          "id": "B",
          "text": "Take a 2-minute breathing break, then open only the first 'URGENT' email to assess the actual threat level.",
          "strategy": "Emotionally Regulated"
        },
        {
          "id": "C",
          "text": "Reply to all 47 emails immediately, staying up late to ensure nothing is missed.",
          "strategy": "Overcompensating"
        },
        {
          "id": "D",
          "text": "Ask a colleague to help you sort through the emails and tell them you're overwhelmed.",
          "strategy": "Assertive/Support-Seeking"
        }
      ]
    },
    {
      "id": 3,
      "title": "The Social Withdrawal",
      "difficulty": 2,
      "narrative": "A friend texts you an invitation to a small gathering tonight. You've been isolating lately due to low mood. The thought of socializing exhausts you, but you also know staying home alone might make the low mood worse.",
      "options": [
        {
          "id": "A",
          "text": "Decline the invitation and spend the evening watching TV alone.",
          "strategy": "Avoidant"
        },
        {
          "id": "B",
          "text": "Accept the invitation but give yourself permission to leave early if it becomes too much.",
          "strategy": "Assertive/Balanced"
        },
        {
          "id": "C",
          "text": "Accept the invitation and force yourself to stay the whole time to prove you're fine.",
          "strategy": "Overcompensating"
        },
        {
          "id": "D",
          "text": "Text back honestly: 'I'm struggling a bit, but I'd like to try to come for a little while.'",
          "strategy": "Emotionally Regulated/Vulnerable"
        }
      ]
    },
    {
      "id": 4,
      "title": "The Therapy Homework",
      "difficulty": 3,
      "narrative": "Your therapist has asked you to practice a 5-minute mindfulness exercise daily. It's day three, and you haven't done it once. You feel guilty and are dreading your next session, worried your therapist will be disappointed in you.",
      "options": [
        {
          "id": "A",
          "text": "Skip the next therapy session to avoid the conversation about not doing the homework.",
          "strategy": "Avoidant"
        },
        {
          "id": "B",
          "text": "Do a shortened 2-minute version right now, then text your therapist to be honest about your struggle.",
          "strategy": "Emotionally Regulated/Assertive"
        },
        {
          "id": "C",
          "text": "Promise yourself you'll do a 20-minute session this weekend to 'make up' for the missed days.",
          "strategy": "Overcompensating"
        },
        {
          "id": "D",
          "text": "Write down what specifically made it hard to do the homework, so you can discuss the barrier in therapy.",
          "strategy": "Analytical"
        }
      ]
    },
    {
      "id": 5,
      "title": "The Midnight Spiral",
      "difficulty": 4,
      "narrative": "It's 2:00 AM. You've been lying in bed for hours, unable to sleep. Your mind is cycling through every mistake you've made this week and every possible bad outcome for tomorrow. The anxiety is a physical weight on your chest.",
      "options": [
        {
          "id": "A",
          "text": "Grab your phone and scroll social media until you feel tired enough to sleep.",
          "strategy": "Avoidant"
        },
        {
          "id": "B",
          "text": "Get out of bed, go to another room, and do a quiet, calming activity until you feel drowsy.",
          "strategy": "Emotionally Regulated"
        },
        {
          "id": "C",
          "text": "Stay in bed and force yourself to think positive thoughts until the anxiety goes away.",
          "strategy": "Suppressive"
        },
        {
          "id": "D",
          "text": "Write down the anxious thoughts in a notebook to 'park' them until morning, then do a body scan relaxation.",
          "strategy": "Analytical/Emotionally Regulated"
        }
      ]
    },
    {
      "id": 6,
      "title": "The Critical Feedback",
      "difficulty": 5,
      "narrative": "Your manager sends you an email with feedback on a recent project. While there are positive notes, there's a section pointing out several areas for improvement. Your immediate reaction is a hot flush of shame and defensiveness. Your mind tells you that you're not good enough.",
      "options": [
        {
          "id": "A",
          "text": "Reply immediately defending your work and explaining why the feedback is unfair.",
          "strategy": "Reactive/Defensive"
        },
        {
          "id": "B",
          "text": "Close the email and don't open it again until your next performance review.",
          "strategy": "Avoidant"
        },
        {
          "id": "C",
          "text": "Read the email once, step away for an hour, then re-read it to separate the emotional reaction from the useful information.",
          "strategy": "Emotionally Regulated/Analytical"
        },
        {
          "id": "D",
          "text": "Forward the email to a trusted coworker and ask them to tell you it's not that bad.",
          "strategy": "Reassurance-Seeking"
        }
      ]
    },
    {
      "id": 7,
      "title": "The Family Obligation",
      "difficulty": 5,
      "narrative": "A family member calls and asks you to help with a stressful event this weekend. You're already exhausted and at your stress limit. Saying yes will drain you, but saying no will cause guilt and potential conflict. You feel trapped between your own needs and family expectations.",
      "options": [
        {
          "id": "A",
          "text": "Say yes immediately and push through the exhaustion to avoid feeling guilty.",
          "strategy": "People-Pleasing"
        },
        {
          "id": "B",
          "text": "Say no firmly without explanation, then turn off your phone to avoid further discussion.",
          "strategy": "Assertive/Abrupt"
        },
        {
          "id": "C",
          "text": "Take a few hours to assess your energy levels, then call back with a clear boundary: 'I can help for two hours, but then I need to rest.'",
          "strategy": "Assertive/Balanced"
        },
        {
          "id": "D",
          "text": "Agree to help but secretly resent the family member the entire time.",
          "strategy": "Passive-Aggressive"
        }
      ]
    },
    {
      "id": 8,
      "title": "The Comparison Trap",
      "difficulty": 4,
      "narrative": "You're scrolling through social media and see a post from an old friend who just got a promotion, bought a house, and looks incredibly happy. A wave of inadequacy crashes over you. Your own progress feels invisible and insignificant in comparison.",
      "options": [
        {
          "id": "A",
          "text": "Keep scrolling and compare yourself to more people to confirm your worst fears about yourself.",
          "strategy": "Self-Destructive"
        },
        {
          "id": "B",
          "text": "Close the app, put your phone in another room, and write down three things you're grateful for in your own life.",
          "strategy": "Emotionally Regulated"
        },
        {
          "id": "C",
          "text": "Immediately sign up for a new course, gym membership, and side hustle to 'catch up' to your friend.",
          "strategy": "Overcompensating"
        },
        {
          "id": "D",
          "text": "Remind yourself that social media is a highlight reel, and send a genuine congratulations message to your friend.",
          "strategy": "Cognitive Reframing/Assertive"
        }
      ]
    },
    {
      "id": 9,
      "title": "The Unexpected Bill",
      "difficulty": 6,
      "narrative": "You open your mailbox to find an unexpected bill for $500 that you weren't prepared for. Your stomach drops. You don't have that amount readily available. Panic starts to set in as you imagine the worst-case financial scenarios.",
      "options": [
        {
          "id": "A",
          "text": "Ignore the bill and shove it in a drawer, hoping the problem will somehow resolve itself.",
          "strategy": "Avoidant"
        },
        {
          "id": "B",
          "text": "Immediately call the company, explain your situation, and ask about payment plan options.",
          "strategy": "Assertive/Problem-Solving"
        },
        {
          "id": "C",
          "text": "Take money from your emergency savings and swear to never speak of this to anyone.",
          "strategy": "Isolating"
        },
        {
          "id": "D",
          "text": "Sit with the panic for 10 minutes, then make a list of your actual financial situation to assess the real impact versus the perceived threat.",
          "strategy": "Emotionally Regulated/Analytical"
        }
      ]
    },
    {
      "id": 10,
      "title": "The Panic Before the Presentation",
      "difficulty": 7,
      "narrative": "You're backstage, about to give a presentation to a room of 50 people. Your hands are shaking, your mouth is dry, and your heart is pounding so hard you can hear it. A voice in your head is screaming that you're going to forget everything and embarrass yourself. You have 3 minutes before you're on.",
      "options": [
        {
          "id": "A",
          "text": "Tell the organizer you're sick and leave through the back door to avoid the situation entirely.",
          "strategy": "Avoidant"
        },
        {
          "id": "B",
          "text": "Do a power pose in the bathroom, repeat a personal affirmation, and focus on your opening line rather than the whole presentation.",
          "strategy": "Emotionally Regulated/Assertive"
        },
        {
          "id": "C",
          "text": "Memorize your entire script word-for-word in the next 3 minutes to ensure perfection.",
          "strategy": "Overcompensating"
        },
        {
          "id": "D",
          "text": "Acknowledge the anxiety out loud to a nearby colleague, take 5 deep breaths, and remind yourself that nervousness and excitement feel the same in the body.",
          "strategy": "Cognitive Reframing/Vulnerable"
        }
      ]
    }
  ]
}
